<?php require __DIR__.'/config.php'; $q=trim($_GET['q']??'');$ticket=null;$searched=false;if($q){$searched=true;$s=db()->prepare("SELECT * FROM tickets WHERE ticket_no=? OR email=? ORDER BY created_at DESC LIMIT 1");$s->execute([$q,$q]);$ticket=$s->fetch();} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Check request — SupportHub</title><link rel="stylesheet" href="assets/style.css"></head><body><nav><a class="brand" href="index.php"><span class="logo">S</span> SupportHub</a><div class="navlinks"><a href="index.php">Help Center</a><a href="submit.php">Contact support</a><a class="active" href="status.php">Check a request</a><a class="adminlink" href="admin/login.php">Admin</a></div></nav><main class="statuswrap"><span class="eyebrow">REQUEST STATUS</span><h1>Check your support request.</h1><form class="search light"><input name="q" value="<?=e($q)?>" placeholder="Ticket number, e.g. SH-260909-ABC123 or email"><button>Search</button></form>
<?php if($searched && !$ticket):?><div class="empty"><h3>No request found</h3><p>Check the ticket number or email and try again.</p></div><?php endif;?>
<?php if($ticket):?><section class="ticket panel"><div class="tickethead"><div><span class="eyebrow">TICKET <?=e($ticket['ticket_no'])?></span><h2><?=e($ticket['subject'])?></h2></div><span class="badge <?=$ticket['status']?>"><?=e(ucfirst($ticket['status']))?></span></div><div class="meta"><span>Category: <?=e($ticket['category'])?></span><span>Priority: <?=e(ucfirst($ticket['priority']))?></span><span>Created: <?=e(date('M j, Y',strtotime($ticket['created_at'])))?></span></div><p class="message"><?=nl2br(e($ticket['message']))?></p><?php if($ticket['admin_note']):?><div class="note"><b>Support update</b><p><?=nl2br(e($ticket['admin_note']))?></p></div><?php endif;?></section><?php endif;?></main></body></html>